def page(title,body,name,extra=''):
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>{E(title)} | ValiStera Academy</title><link rel="stylesheet" href="/assets/academy/module-3/course.css"><script defer src="/assets/academy/module-3/course.js"></script></head><body {extra}><a class="skip" href="#main">Skip to learning content</a><header class="site-header"><div class="brand">Vali<b>Stera</b><small>ACADEMY</small></div><nav class="navlinks" aria-label="Module navigation"><a href="/academy-module-3.html">Module overview</a><a href="/academy-module-3-workbook.html">Workbook</a><a href="/academy-module-3-assessment.html">Assessment</a></nav></header><main id="main" tabindex="-1">{body}</main>{footer}</body></html>'''
 out=re.sub(r'(/assets/academy/module-3/[^\"<> ]+\.(?:mp4|png|vtt|css|js))(?=[\"])',lambda m:m[1]+'?v='+hashlib.sha256((R/m[1].lstrip('/')).read_bytes()).hexdigest()[:12] if (R/m[1].lstrip('/')).exists() else m[1],out)
