for l in D['lessons']:
 i=l['id'];p=A/f'lesson-{i}-timing.json';t=json.loads(p.read_text()) if p.exists() else {'duration':0}
 body=f'<div class="eyebrow">Module 03 / Lesson 3.{i} · Review candidate</div><h1>{E(l["title"])}</h1><p class="lede">{E(l["objective"])}</p><p class="muted">{t["duration"]/60:.1f} minutes · English captions · Illustrations and worked example</p><p>This lesson’s core explanations and worked-example reasoning are narrated. The table restates the example for reference; the practice activity and model answer are reading exercises.</p><section class="panel" aria-label="Lesson video"><button id="load-media" class="play" aria-label="Play lesson 3.{i}"><img src="/assets/academy/module-3/lesson-{i}-scene-1.png" alt="" width="1280" height="720"><span class="academy-play-label">▶ Play lesson</span></button><video id="video" hidden tabindex="0" controls playsinline preload="none" data-src="/assets/academy/module-3/lesson-{i}.mp4" aria-label="Lesson 3.{i}: {E(l["title"])}"><track kind="captions" src="/assets/academy/module-3/lesson-{i}.vtt" srclang="en" label="English" default></video><div class="caption-controls"><button type="button" id="toggle-captions" aria-pressed="true">Subtitles: On</button><p id="caption-status" role="status">English captions available.</p></div><p id="media-status" role="status"></p><noscript><a href="/assets/academy/module-3/lesson-{i}.mp4">Open video</a></noscript><p><a href="#transcript">Read the lesson</a> · <a href="/assets/academy/module-3/lesson-{i}.vtt" download>Download captions</a> · <a href="/assets/academy/module-3/lesson-{i}-transcript.txt" download>Download transcript</a></p></section><section id="transcript"><h2>Narration and visual explanations</h2><p>Open View Technical Explanation to see each diagram, its text description and the matching narration. Standard abbreviations and numerals are used visually.</p>'
 for j,s in enumerate(l['scenes'],1):
  base={1:'The left panel shows a simplified mixing vessel, agitator, temperature instrument and outlet. ',3:'The left chart shows sensor, transmitter and display bounds of 0.2 °C each, with a 0.6 °C sum and a fictional 0.5 °C limit. ',4:'The left panel shows the vessel contact path through its outlet, with a temperature instrument. ',5:'The left panel shows a single shared sensor branching to controller and alarm. ',6:'The left panel shows a jacketed vessel with a utility/measurement connection and outlet. ',10:'The left panel has eight cyan and two amber cells out of ten; the 80% label is coverage, not acceptance. '}.get(i,'The left panel links the three labelled concepts in reading order. ')
  if i==4 and j in [3,4]:base='The left panel contrasts a continuous outlet with a low pocket holding liquid below outlet level. No universal slope or dimensional limit is specified. '
  if i==6 and j==2:base='The left plan view shows the vessel, rear instrument, and dashed removal path blocked by an adjacent pipe rack. No minimum clearance dimension is specified. '
  body+=f'<section class="panel"><div class="eyebrow">Part {j} of 4</div><h3>{E(s["title"])}</h3><details class="scene-explanation"><summary>View Technical Explanation <span class="muted">· Diagram {j}</span></summary><div class="technical-content"><figure><a href="/assets/academy/module-3/lesson-{i}-scene-{j}.png" aria-label="Open full-size diagram: {E(s["title"])}"><img loading="lazy" src="/assets/academy/module-3/lesson-{i}-scene-{j}.png" width="1280" height="720" alt="{E(s["title"])} — diagram {j}. Description below."></a><figcaption>{E(base+s["description"])} Key points: {E("; ".join(s["labels"]))}.</figcaption></figure><h4>Lesson explanation</h4><p>{E(display(s["narration"]))}</p></div></details></section>'
 body+='</section><section class="panel"><h2>Worked example</h2>'+table(l['worked'])+'</section>'
 if i==3:body+='<section class="panel"><h2>Explore the conservative error bound</h2><p>Positive component bounds in °C; sum assumes aligned errors. Fictional requirement 0.50 °C. This arithmetic is not a full uncertainty budget.</p>'+''.join(f'<label for="error-{n}">{label} bound (°C)</label><input id="error-{n}" data-error-component type="number" min="0" max="2" step="0.1" value="0.2">' for n,label in enumerate(['Sensor','Transmitter','Display'],1))+'<p id="error-result" role="status">Worst-case sum: 0.60 °C. Exceeds the fictional 0.50 °C requirement.</p></section>'
 if i==10:body+='<section class="panel"><h2>Coverage is not acceptance</h2><label for="covered">Requirements with supported design evidence (out of 10)</label><input id="covered" type="number" min="0" max="10" step="1" value="8"><p id="coverage-result" role="status">8 of 10 = 80% coverage. Review important gaps; no percentage authorizes use.</p></section>'
 body+=f'<section class="panel"><h2>Apply it · Activity {i}</h2><p>{E(l["activity"])}</p><a href="/academy-module-3-workbook.html#activity-{i}">Open workbook activity</a><details><summary>Compare with model reasoning</summary><p>{E(l["model"])}</p></details></section><section class="panel"><h2>Knowledge check</h2><form class="quiz" data-lesson="{i}">'+quiz(l['quiz'],1)+'<button type="submit" disabled>Check answer</button><p class="quiz-result" role="status"></p></form></section>'
 body+='<button type="button" id="mark-studied">Mark this lesson studied</button><p id="studied-status" role="status"></p><nav class="lesson-nav" aria-label="Lesson sequence">'+(f'<a href="/academy-lesson-3-{i-1}.html">← Previous lesson</a>' if i>1 else '<a href="/academy-module-3.html">← Overview</a>')+(f'<a href="/academy-lesson-3-{i+1}.html">Next lesson →</a>' if i<10 else '<a href="/academy-module-3-assessment.html">Final assessment →</a>')+'</nav><details><summary>Technical sources</summary>'+links()+'</details>'
