runtime=sum(json.loads(p.read_text())['duration'] for p in A.glob('lesson-*-timing.json'))
body=f'<section class="hero"><div class="eyebrow">Module 03 · Review candidate</div><h1>Design Qualification (DQ)</h1><p class="lede">Turn a proposed pharmaceutical design into a defensible, evidence-linked decision.</p><p><span class="pill">10 narrated lessons</span><span class="pill">40 diagrams</span><span class="pill">10 worked examples</span><span class="pill">2 interactive explorers</span></p><a class="button" href="/academy-lesson-3-1.html">Start Lesson 3.1 →</a></section><div class="grid"><section class="panel"><h2>Continue the V-201 case</h2><p>Review a fictional oral-liquid mixing vessel. No aseptic process, site-specific acceptance criteria or actual qualification records are represented.</p><p>Prerequisite: <a href="/academy-module-2.html">Module 2 — VMP, URS and Risk Assessment</a>.</p></section><section class="panel"><h2>Learning time and format</h2><p>{runtime/60:.1f} minutes of narration. Allow approximately 4–5 hours including 200 minutes of suggested practice, reading and assessment. These are unmeasured planning estimates, not accredited contact time.</p><p>Core explanations and worked reasoning are narrated. Reference tables restate the examples; activities and model answers are reading exercises.</p></section></div><section class="panel"><h2>Your self-study progress</h2><p id="progress-text">0 of 10 lessons marked studied · 0 of 10 checks passed</p><progress id="progress-bar" max="10" value="0" aria-label="Lessons marked studied"></progress><p id="assessment-status">Final assessment not completed.</p><p>Saving is optional and defaults off. Progress is not a GMP training record.</p></section><h2>Lessons</h2><div class="grid">'
for l in D['lessons']:body+=f'<article class="panel"><div class="eyebrow">Lesson 3.{l["id"]}</div><h3>{E(l["title"])}</h3><p>{E(l["objective"])}</p><a href="/academy-lesson-3-{l["id"]}.html">Open lesson 3.{l["id"]} →</a></article>'
body+='</div><p><a href="/academy-module-3-workbook.html">Workbook and templates</a> · <a href="/academy-module-3-assessment.html">20-question assessment</a> · <a href="/academy-module-3-sources.html">Sources and privacy</a> · <a href="/academy-module-3-review.html">Review package</a></p>'
page(D['title'],body,'academy-module-3.html')
body='<h1>DQ practical workbook</h1><p class="lede">Develop a controlled review baseline, traceability row, finding register and handover decision.</p><p>Fictional V-201 oral-liquid vessel only. Do not enter confidential site or patient data. Answers are not stored or transmitted; print before closing.</p><button id="print-workbook" type="button">Print / save workbook as PDF</button><p><a href="/assets/academy/module-3/dq-template.csv" download>DQ traceability template (CSV)</a> · <a href="/assets/academy/module-3/findings-template.csv" download>Design findings template (CSV)</a></p>'
for l in D['lessons']:
 i=l['id'];body+=f'<section class="panel" id="activity-{i}"><h2>Activity {i} · {E(l["title"])}</h2><p>Suggested time: 20 minutes. Revisit the narrated lesson and worked example before responding.</p><p>{E(l["activity"])}</p><label for="work-{i}">Your response</label><textarea id="work-{i}"></textarea><details><summary>Model reasoning</summary><p>{E(l["model"])}</p></details><a href="/academy-lesson-3-{i}.html">Revisit lesson</a></section>'
