page('DQ practical workbook',body,'academy-module-3-workbook.html')
body='<h1>Apply the DQ reasoning</h1><p>20 distinct application questions. This open-book self-study assessment exposes its answer key in the source and below. The suggested practice target is 80%, not a regulatory threshold, DQ acceptance rule or proof of independent competence. Unanswered questions must be completed before scoring. Answers are not sent to a server.</p><form class="quiz" data-final="true">'+''.join(quiz(q,i) for i,q in enumerate(QUESTIONS,1))+'<button type="submit" disabled>Score assessment</button><p class="quiz-result" role="status" tabindex="-1"></p></form><details><summary>Answer key and explanations</summary>'+''.join(f'<p>{i}. {E(q["options"][q["answer"]])} — {E(q["feedback"])}</p>' for i,q in enumerate(QUESTIONS,1))+'</details><noscript><p>Interactive scoring requires JavaScript; use the answer key for self-review.</p></noscript>'
